-- Data-only migration: make "UserProfile" the single source for the seeded creator profiles
-- that were previously read from data/<profile>.json at runtime. A row is inserted only when the
-- creator has a linked account and no profile exists yet; existing profiles are left untouched.

INSERT INTO "UserProfile" (
  id, "userId", slug, "displayName", handle, "avatarInitials", "avatarColor", "avatarUrl", "coverUrl",
  bio, verified, "specialRequests", "subscriptionPriceLabel", "followersLabel", "followingCount",
  "subscribersCount", "postsCountLabel", "popularPostsJson", "pinnedFeedPostIds", source,
  "createdAt", "updatedAt"
)
SELECT
  'c' || substr(md5(random()::text || clock_timestamp()::text || v.slug), 1, 24),
  c."userId", v.slug, v.display_name, v.handle, v.avatar_initials, v.avatar_color, v.avatar_url,
  v.cover_url, v.bio, v.verified, v.special_requests, v.price_label, v.followers_label,
  v.following_count, v.subscribers_count, v.posts_count, v.popular_posts,
  ARRAY(
    SELECT t.id
    FROM unnest(v.pins) WITH ORDINALITY AS t(id, n)
    WHERE EXISTS (SELECT 1 FROM "FeedPost" f WHERE f.id = t.id)
    ORDER BY t.n
  ),
  'profile-json', now(), now()
FROM (VALUES
  ('bathiya-santhush', 'Bathiya and Santhush', '@bnsofficial', 'BS', '#b45309', '/assets/creators/bathiya-santhush/avatar.jpg', '/assets/creators/bathiya-santhush/cover.jpg', 'Sri Lanka’s iconic pop duo. Two decades of anthems, live nights, and songs that still fill every wedding playlist from Colombo to Kandy.', true, false, NULL, '1.2M', 86, 0, 3, '[{"title":"Soundcheck in Colombo — new stage, same roar","posted_ago":"2h","likes":"18.4K","comments":"1.2K","image":"/assets/creators/bathiya-santhush/feed.jpg","members_only":false,"has_video":false},{"title":"Vasanthaye still hits different in 2026","posted_ago":"1d","likes":"9.6K","comments":"640","image":"/assets/creators/bathiya-santhush/feed-wedding.jpg","members_only":false,"has_video":false},{"title":"Backstage before Kandy — two voices, one mic check","posted_ago":"4d","likes":"7.1K","comments":"418","image":"/assets/creators/bathiya-santhush/feed-stage.jpg","members_only":false,"has_video":false}]'::jsonb, ARRAY['bns-001', 'bns-002', 'bns-003']::text[]),
  ('billie-eilish', 'Billie Eilish', '@billieeilish', 'BE', '#0369a1', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=240&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=1400&h=400&fit=crop', 'Grammy-winning artist. Dark-pop, whisper-vocal anthems, and a generation of listeners who grew up on her records.', true, false, NULL, '12.4M', 0, 0, 0, NULL::jsonb, ARRAY[]::text[]),
  ('dev-weekly', 'Dev Weekly', '@devweekly', 'DW', '#7c3aed', 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=120&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=1400&h=400&fit=crop', 'Weekly deep dives on AI, mobile, and the tools reshaping how we build. Breaking down launches, benchmarks, and architecture decisions without the hype.', true, false, 'Subscribe · $4.99/mo', '48.2K', 312, 2840, 142, '[{"title":"On-device AI translation under 200 ms","posted_ago":"1 day ago","likes":"12.8K","comments":"967","image":"https://images.unsplash.com/photo-1518770660439-4636190af475?w=520&h=325&fit=crop","members_only":false,"has_video":false},{"title":"Why local-first sync won our hackathon","posted_ago":"2 weeks ago","likes":"6.4K","comments":"412","image":"https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=520&h=325&fit=crop","members_only":true,"has_video":true},{"title":"Rust in production — 6 months later","posted_ago":"1 month ago","likes":"9.1K","comments":"638","image":"https://images.unsplash.com/photo-1627398242454-45a1465c2479?w=520&h=325&fit=crop","members_only":false,"has_video":false}]'::jsonb, ARRAY['dw-001', 'dw-002', 'dw-003', 'dw-004', 'dw-005', 'dw-006', 'dw-007', 'dw-008']::text[]),
  ('good-guy-podcast', 'Good Guy Podcast', '@goodguypod', 'GG', '#6b5b4f', 'https://images.unsplash.com/photo-1518609878373-06d740f60d8b?w=120&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=1400&h=400&fit=crop', 'Long-form conversations on creativity, discipline, and building in public. Two hosts, one mic, zero fluff. Members get uncut episodes, early drops, and studio notes.', true, false, 'Subscribe · $5.99/mo', '186K', 214, 12400, 96, '[{"title":"Episode 14 — creativity, discipline, building in public","posted_ago":"1 day ago","likes":"2.8K","comments":"186","image":"https://images.unsplash.com/photo-1516280440614-37939bbacd81?w=520&h=325&fit=crop","members_only":false,"has_video":false},{"title":"Uncut: the 40 minutes we left on the floor","posted_ago":"3 days ago","likes":"1.1K","comments":"94","image":"https://images.unsplash.com/photo-1590602847861-f357a9332bbc?w=520&h=325&fit=crop","members_only":true,"has_video":false},{"title":"Studio notes — how we cut four hours to forty","posted_ago":"1 week ago","likes":"940","comments":"71","image":"https://images.unsplash.com/photo-1478737270239-2f02b77fc618?w=520&h=325&fit=crop","members_only":true,"has_video":false}]'::jsonb, ARRAY['ggp-001', 'ggp-002', 'ggp-003', 'ggp-004', 'ggp-005', 'ggp-006', 'ggp-007']::text[]),
  ('hard-fork', 'Hard Fork', '@hardfork', 'HF', '#0f766e', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=240&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=1400&h=400&fit=crop', 'The Verge’s weekly tech podcast. AI, platforms, and the culture of building — with a side of music and the creator economy.', true, false, NULL, '2.1M', 0, 0, 0, NULL::jsonb, ARRAY[]::text[]),
  ('hiran', 'Hiran', '@hiran', 'HI', '#0d9488', NULL, NULL, 'Filmmaker and tinkerer. Sharing rough cuts, creative experiments, and the messy middle between an idea and something worth showing.', false, false, NULL, '1.2K', 186, 0, 28, '[{"title":"My first short film premiere","posted_ago":"2 days ago","likes":"214","comments":"47","image":"https://images.unsplash.com/photo-1485846234645-a62644f84728?w=520&h=325&fit=crop","members_only":false,"has_video":true},{"title":"Storyboard to final frame","posted_ago":"2 weeks ago","likes":"128","comments":"31","image":"https://images.unsplash.com/photo-1478720568477-152d9b164e26?w=520&h=325&fit=crop","members_only":false,"has_video":false},{"title":"Late-night edit session notes","posted_ago":"1 month ago","likes":"96","comments":"22","image":"https://images.unsplash.com/photo-1574717024653-61fd2cf4d44d?w=520&h=325&fit=crop","members_only":false,"has_video":false}]'::jsonb, ARRAY['hir-001', 'hir-002', 'hir-003', 'hir-004', 'hir-005']::text[]),
  ('inrcliq-originals', 'INRCLIQ Originals', '@inrcliq', 'IO', '#b45309', NULL, 'https://images.unsplash.com/photo-1589903308904-1010c2294adc?w=1400&h=400&fit=crop', 'Original podcasts from INRCLIQ — conversations with builders, creators, and the people shaping culture.', true, false, NULL, '640K', 0, 0, 0, NULL::jsonb, ARRAY[]::text[]),
  ('james-clear', 'James Clear', '@jamesclear', 'JC', '#4338ca', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=240&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=1400&h=400&fit=crop', 'Author of Atomic Habits. Practical systems for getting 1% better every day — in writing, audio, and the habits behind both.', true, false, NULL, '890K', 0, 0, 0, NULL::jsonb, ARRAY[]::text[]),
  ('mia-chen', 'Mia Chen', '@miachenruns', 'MC', '#2563eb', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=120&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?w=1400&h=400&fit=crop', 'Ultramarathon runner based in Mumbai. Sharing training logs, race-day stories, and honest recovery notes from the road. Members get weekly plans and early race vlogs.', true, true, 'Subscribe · $4.99/mo', '12.4K', 842, 186, 69, '[{"title":"42 km before sunrise","posted_ago":"3 days ago","likes":"4.8K","comments":"312","image":"https://images.unsplash.com/photo-1552674605-db6ffd4facb5?w=520&h=325&fit=crop","members_only":true,"has_video":false},{"title":"Monsoon hill repeats · 12×400 m","posted_ago":"2 weeks ago","likes":"2.1K","comments":"148","image":"https://images.unsplash.com/photo-1502904550040-7534597429ae?w=520&h=325&fit=crop","members_only":true,"has_video":false},{"title":"What I eat on long-run Sundays","posted_ago":"1 month ago","likes":"3.6K","comments":"421","image":"https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=520&h=325&fit=crop","members_only":false,"has_video":true}]'::jsonb, ARRAY['mia-001', 'mia-002', 'mia-audio-001', 'mia-003', 'mia-004', 'mia-005', 'mia-006', 'mia-007', 'mia-008']::text[]),
  ('planet-unfolded', 'Planet Unfolded', '@planetunfolded', 'PU', '#0369a1', NULL, 'https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?w=1400&h=400&fit=crop', 'Award-winning science and nature documentaries. From deep-ocean vents to distant galaxies — we film what most people never get to see. Members get early episodes, director commentary, and behind-the-scenes field logs.', true, false, 'Subscribe · $6.99/mo', '2.8M', 124, 48200, 312, '[{"title":"Life without sunlight · deep-sea vents","posted_ago":"2 days ago","likes":"67.8K","comments":"2.9K","image":"https://images.unsplash.com/photo-1559827260-dc66d52bef19?w=520&h=325&fit=crop","members_only":true,"has_video":true},{"title":"Inside the James Webb first-light archive","posted_ago":"2 weeks ago","likes":"41.2K","comments":"1.8K","image":"https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?w=520&h=325&fit=crop","members_only":true,"has_video":false},{"title":"How we filmed a glacier calving at 4K","posted_ago":"1 month ago","likes":"28.6K","comments":"942","image":"https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=520&h=325&fit=crop","members_only":false,"has_video":true}]'::jsonb, ARRAY['pu-001', 'pu-002', 'pu-003', 'pu-004', 'pu-005', 'pu-006', 'pu-007', 'pu-008']::text[]),
  ('taylor-swift', 'Taylor Swift', '@taylorswift', 'TS', '#1e3a5f', 'https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=240&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?w=1400&h=400&fit=crop', 'Songwriter, storyteller, and one of the most-streamed artists in the world. Eras, re-records, and the nights in between.', true, false, NULL, '28.6M', 0, 0, 0, NULL::jsonb, ARRAY[]::text[])
) AS v(
  slug, display_name, handle, avatar_initials, avatar_color, avatar_url, cover_url, bio, verified,
  special_requests, price_label, followers_label, following_count, subscribers_count, posts_count,
  popular_posts, pins
)
JOIN "CreatorUser" c ON lower(c.slug) = v.slug AND c."userId" IS NOT NULL
WHERE NOT EXISTS (
  SELECT 1 FROM "UserProfile" up WHERE up."userId" = c."userId" OR lower(up.slug) = v.slug
)
ON CONFLICT DO NOTHING;
